1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	
4	<head>
5	  <!-- 适用范围：content-template.html 仅用于内容页(content)；结构页(cover/agenda/section/ending)请勿套用，各自有对应模板，按 style.md「模板使用规则」字面拷贝。配色/字体以 style.md 为唯一权威。 -->
6	  <meta charset="UTF-8">
7	  <meta name="viewport" content="width=1280, height=720">
8	  <title>{{PAGE_TITLE}}</title>
9	
10	  <!-- Tailwind CSS（必选） -->
11	  <script src="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/vendors/tailwind.js"></script>
12	  <script src="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/vendors/echarts.min.js"></script>
13	
14	  <!-- 字体引用 -->
15	  <link href="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/css/fonts.css" rel="stylesheet" />
16	
17	  <!-- Tailwind 配置：商务经典风格配色（以 style.md 为唯一权威） -->
18	  <script>
19	    tailwind.config = {
20	      theme: {
21	        extend: {
22	          colors: {
23	            brandRed: "#D33941",
24	            brandRedLight: "#E18189",
25	            brandRedLighter: "#EFB2B8",
26	            brandRedPale: "#EEB3C1",
27	            brandRedBg: "#FFF1EF",
28	            brandRedDeep: "#D33859",
29	            brandRedRose: "#E18198",
30	            grayDeep: "#555757",
31	            gray1: "#898989",
32	            gray2: "#B5B5B5",
33	            gray3: "#DDDDDD",
34	            gray4: "#F5F5F5",
35	            magenta: "#C40054",
36	            redDeep: "#7F0001",
37	            orange: "#ED6D00",
38	            yellow: "#FDD351",
39	            green: "#62B230",
40	            cyan: "#30B5C5",
41	          },
42	          fontFamily: {
43	            sans: ["WenYuan Sans SC", "Arial", "Noto Sans SC", "sans-serif"],
44	          },
45	        },
46	      },
47	    };
48	  </script>
49	
50	  <!-- 防溢出硬性约束 → 全局 CSS 约束（逐字包含） -->
51	  <style type="text/tailwindcss">
52	    @layer utilities {
53	      /* 幻灯片容器 */
54	      .ppt-slide {
55	        @apply relative w-[1280px] h-[720px] mx-auto box-border overflow-hidden;
56	      }
57	
58	      /* 全局防溢出约束 - 应用到所有子元素 */
59	      .ppt-slide *,
60	      .ppt-slide *::before,
61	      .ppt-slide *::after {
62	        @apply box-border;
63	        max-width: 100%;
64	      }
65	
66	      /* 图片/视频/图表防溢出 */
67	      .ppt-slide img {
68	        @apply max-w-full max-h-full;
69	      }
70	
71	      .ppt-slide video,
72	      .ppt-slide svg,
73	      .ppt-slide .echarts-main,
74	      .ppt-slide .chart-container,
75	      .ppt-slide [id*="chart" i] {
76	        @apply max-w-full max-h-full object-contain;
77	      }
78	
79	      /* 图表容器高度防御 */
80	      .ppt-slide [id*="chart" i],
81	      .ppt-slide .chart-container,
82	      .ppt-slide .echarts-main {
83	        width: 100%;
84	        height: 100%;
85	        min-height: 160px;
86	      }
87	
88	      /* 图表包装器高度防御 */
89	      .ppt-slide :has(> [id*="chart" i]),
90	      .ppt-slide :has(> .chart-container),
91	      .ppt-slide :has(> .echarts-main) {
92	        min-height: 160px;
93	      }
94	
95	      /* 内容安全区：核心内容容器（边距由此统一提供） */
96	      .content-safe {
97	        @apply w-[1220px] h-[660px] my-[30px] mx-auto flex flex-col overflow-hidden;
98	      }
99	
100	      /* 禁止模糊滤镜效果 */
101	      .ppt-slide [class*="blur"],
102	      .ppt-slide [style*="blur"] {
103	        filter: none !important;
104	        backdrop-filter: none !important;
105	      }
106	
107	      /* 禁止半透明渐变背景，使用纯色替代 */
108	      .ppt-slide [class*="gradient"] {
109	        background-image: none !important;
110	      }
111	
112	      /* 禁止毛玻璃效果 */
113	      .ppt-slide [class*="backdrop-blur"],
114	      .ppt-slide [style*="backdrop-filter"] {
115	        backdrop-filter: none !important;
116	      }
117	
118	      /* 全局字体设置：商务经典风格 */
119	      .ppt-slide {
120	        font-family: "WenYuan Sans SC", "Arial", "Noto Sans SC", sans-serif !important;
121	      }
122	    }
123	  </style>
124	
125	  <!-- 全局文字颜色 -->
126	  <style>
127	    body {
128	      color: #555757;
129	    }
130	  </style>
131	</head>
132	
133	<body>
134	  <div class="ppt-slide flex flex-col bg-white" type="content">
135	    <div class="content-safe">
136	      <!-- 标题栏（跨页锚点片段：文字样式逐字复用，边距由 content-safe 统一提供） -->
137	      <div class="pt-[16px] pb-[16px] flex-shrink-0">
138	        <h1 class="text-[37px] font-medium text-black leading-tight">
139	          {{PAGE_TITLE}}
140	        </h1>
141	      </div>
142	
143	      <!-- 主视觉区：弹性填充 -->
144	      <main class="flex-1 min-h-0 flex flex-col justify-center overflow-hidden">
145	        {{PAGE_CONTENT}}
146	      </main>
147	
148	      <!-- 页脚/注释区（跨页锚点片段：文字样式逐字复用） -->
149	      <div class="pt-[16px] pb-[16px] flex-shrink-0">
150	        <p class="text-[12px] italic text-gray1">
151	          {{PAGE_FOOTER}}
152	        </p>
153	      </div>
154	    </div>
155	  </div>
156	
157	    <!-- CHART_SCAFFOLD_BEGIN
158	    <script>
159	      /*
160	       * 图表骨架（图表候选页激活；非图表页保持注释即可，对浏览器与 fix 零副作用）。
161	       * 重要：说明文字必须写在本 script 内的 JS 块注释中，禁止写在 HTML 注释定界符与
162	       * script 之间（否则激活后会成为页面可见裸文本）。
163	       *
164	       * 激活步骤：
165	       *   1) 在 PAGE_CONTENT 放置图表容器，标准写法：
166	       *        div.flex.flex-col > div.flex-1.min-h-0 > div#chart-1.w-full.h-full
167	       *      （容器硬约束：flex flex-col 套 flex-1 min-h-0 套 w-full h-full；可读高度建议 >=300px）
168	       *   2) 成对删除首尾两个定界符：开头的 HTML 注释起始（含 CHART_SCAFFOLD_BEGIN）
169	       *      与结尾的 CHART_SCAFFOLD_END 注释结束，保留中间的 script。
170	       *   3) 把下方 const option = null 的 null 替换为图表 option 对象。
171	       *
172	       * 骨架已内置硬约束（机制勿改）：SVG renderer · animation:false 强制 · 全局 textStyle.fontFamily · IIFE · formatter 外部函数。
173	       * CHART_FONT_FAMILY 必须等于当前风格 style.md（custom 为 style-custom.md）frontmatter 的完整字体栈：
174	       *   预设风格模板已预置正确值（勿改）；custom 模板为中性占位值，必须替换后再激活。
175	       * 仍需 designer 自觉遵守（骨架不强制）：
176	       *   - 禁止渐变（colorStops、type 为 linear 或 radial、echarts.graphic.LinearGradient 等会触发导出位图化）；
177	       *     折线/面积图 areaStyle.color 用半透明纯色，如 rgba(<风格主色>, 0.18)，色值以 style.md 为准。
178	       *   - 坐标轴/图例/数据标签的 fontFamily/color 按 style.md 图表色规范设置。
179	       * 设计约束：外层 HTML 注释（BEGIN 与 END 之间）任何位置都不得出现 HTML 注释结束符
180	       * 或连续减号，否则会提前终止外层注释、让非图表页误执行图表代码。
181	       * 多图表：每段独立成 HTML 注释块（CHART_SCAFFOLD_BEGIN 与 CHART_SCAFFOLD_2_BEGIN ），并把第二段标签改为 _2_ 以便区分；切勿把第二段粘贴到第一段注释内部，否则外层注释会在内层第一个 HTML标签注释结束符（减号减号大于号）处提前闭合。改 id（chart-1 改 chart-2）与 getElementById 入参。
182	       */
183	      (function () {
184	        const CHART_FONT_FAMILY = "WenYuan Sans SC, Arial, Noto Sans SC, sans-serif";
185	        // formatter 外部函数模板：
186	        //   axisLabel / xAxis / yAxis 的 formatter 接收原始数值；
187	        //   series.label / tooltip 的 formatter 接收 params 对象（需取 .value）。
188	        // 最多保留小数点后三位，去除末尾多余的零（循环小数如 1/3=0.333... 显示为 0.333）
189	        function trimNumber(v) {
190	          if (v == null || v === "") return "";
191	          var s = Number(v).toFixed(3);
192	          s = s.replace(/(\.\d*?)0+$/, "$1").replace(/\.$/, "");
193	          return s;
194	        }
195	        function formatAxisNumber(v) {
196	          if (v >= 1e8) return (v / 1e8).toFixed(1) + "亿";
197	          if (v >= 1e4) return (v / 1e4).toFixed(1) + "万";
198	          return trimNumber(v);
199	        }
200	        function formatAxisPercent(v) {
201	          return (v * 100).toFixed(1) + "%";
202	        }
203	        function formatLabelNumber(p) {
204	          var v = typeof p === "object" ? p.value : p;
205	          if (v == null) return "";
206	          if (v >= 1e8) return (v / 1e8).toFixed(1) + "亿";
207	          if (v >= 1e4) return (v / 1e4).toFixed(1) + "万";
208	          return trimNumber(v);
209	        }
210	        function formatLabelPercent(p) {
211	          var v = typeof p === "object" ? p.value : p;
212	          if (v == null) return "";
213	          return (v * 100).toFixed(1) + "%";
214	        }
215	        const el = document.getElementById("chart-1");
216	        if (!el) return;
217	        // 激活后把下方 null 替换为图表 option 对象，例如：
218	        //   { xAxis:{type:"category",data:[...]}, yAxis:{type:"value"}, series:[{data:[...],type:"bar"}] }
219	        // 注意：option 校验必须在 echarts.init 之前，否则未替换 null 时仍会创建实例并产出空 SVG，
220	        // 进而被 convert 阶段渲染为空图（fix 已不再落盘 ECharts，由 convert 阶段现场渲染）。
221	        const option = null;
222	        if (!option) return; // 未填 option 则跳过，避免执行 echarts.init 产出空图
223	        const chart = echarts.init(el, null, { renderer: "svg" });
224	        option.animation = false; // 强制禁动画，PPT 静态输出必须禁用，不可覆盖
225	        option.textStyle = Object.assign({ fontFamily: CHART_FONT_FAMILY }, option.textStyle);
226	        chart.setOption(option);
227	      })();
228	    </script>
229	    CHART_SCAFFOLD_END -->
230	</body>
231	
232	</html>
